import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a CTA-tiled 3D convolution.
#
# Structural optimization applied: CTA-level spatial (H,W) output tiling with
# shared-memory staging of the reusable input tile. Each CTA is responsible
# for a TILE_H x TILE_W (16x16) block of output pixels for a fixed (n, co, od)
# triple. For every (cin, kd) pair, the CTA cooperatively loads the
# corresponding 2D input patch (covering the halo needed for all kh/kw and
# all threads in the tile) into shared memory once, then every thread in the
# CTA reuses that shared data for its own kh/kw accumulation instead of
# re-reading global memory redundantly. This removes the massive redundant
# global-memory traffic that a pure "one thread per output, direct global
# loads" kernel incurs, while preserving exact stride/padding/dilation/groups
# semantics.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry conv3d_kernel(
    .param .u64 param_x,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_y,
    .param .u32 param_N,
    .param .u32 param_Cin,
    .param .u32 param_D,
    .param .u32 param_H,
    .param .u32 param_Win,
    .param .u32 param_Cout,
    .param .u32 param_K,
    .param .u32 param_stride,
    .param .u32 param_padding,
    .param .u32 param_dilation,
    .param .u32 param_Dout,
    .param .u32 param_Hout,
    .param .u32 param_Wout,
    .param .u32 param_CinPerGroup,
    .param .u32 param_CoutPerGroup
)
{
    .reg .pred %p<40>;
    .reg .b32  %r<140>;
    .reg .b64  %rd<140>;
    .reg .f32  %f<8>;

    .shared .align 4 .f32 smem[1024];

    ld.param.u64 %rd1, [param_x];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_y];

    ld.param.u32 %r1,  [param_N];
    ld.param.u32 %r2,  [param_Cin];
    ld.param.u32 %r3,  [param_D];
    ld.param.u32 %r4,  [param_H];
    ld.param.u32 %r5,  [param_Win];
    ld.param.u32 %r6,  [param_Cout];
    ld.param.u32 %r7,  [param_K];
    ld.param.u32 %r8,  [param_stride];
    ld.param.u32 %r9,  [param_padding];
    ld.param.u32 %r10, [param_dilation];
    ld.param.u32 %r11, [param_Dout];
    ld.param.u32 %r12, [param_Hout];
    ld.param.u32 %r13, [param_Wout];
    ld.param.u32 %r14, [param_CinPerGroup];
    ld.param.u32 %r15, [param_CoutPerGroup];

    cvta.to.global.u64 %rd5, %rd1;   // Xg
    cvta.to.global.u64 %rd6, %rd2;   // Wg
    cvta.to.global.u64 %rd7, %rd4;   // Yg
    cvta.to.global.u64 %rd8, %rd3;   // Bg

    mov.u32 %r16, %tid.x;
    mov.u32 %r17, %tid.y;
    mov.u32 %r18, %ctaid.x;
    mov.u32 %r19, %ctaid.y;
    mov.u32 %r20, %ctaid.z;

    mov.u32 %r21, 16;     // TILE_W
    mov.u32 %r22, 16;     // TILE_H

    mad.lo.s32 %r23, %r18, %r21, %r16;   // ow
    mad.lo.s32 %r24, %r19, %r22, %r17;   // oh

    div.s32 %r25, %r20, %r11;   // ctaid.z / Dout
    rem.s32 %r26, %r20, %r11;   // od
    div.s32 %r27, %r25, %r6;    // n
    rem.s32 %r28, %r25, %r6;    // co

    setp.lt.s32 %p1, %r24, %r12;
    setp.lt.s32 %p2, %r23, %r13;
    and.pred  %p3, %p1, %p2;    // valid_out

    div.s32 %r29, %r28, %r15;   // group
    mul.lo.s32 %r30, %r29, %r14; // cin_start

    mov.f32 %f1, 0f00000000;
    setp.eq.s64 %p4, %rd3, 0;
    @%p4 bra L_BIAS_DONE;
    mul.wide.s32 %rd9, %r28, 4;
    add.s64 %rd10, %rd8, %rd9;
    ld.global.f32 %f1, [%rd10];
L_BIAS_DONE:

    cvt.s64.s32 %rd11, %r4;
    cvt.s64.s32 %rd12, %r5;
    mul.lo.s64 %rd13, %rd11, %rd12;   // sXd = H*Win
    cvt.s64.s32 %rd14, %r3;
    mul.lo.s64 %rd15, %rd14, %rd13;   // sXc = D*H*Win
    cvt.s64.s32 %rd16, %r2;
    mul.lo.s64 %rd17, %rd16, %rd15;   // sXn

    cvt.s64.s32 %rd18, %r7;
    mul.lo.s64 %rd19, %rd18, %rd18;   // KK
    mul.lo.s64 %rd20, %rd19, %rd18;   // KKK
    cvt.s64.s32 %rd21, %r14;
    mul.lo.s64 %rd22, %rd21, %rd20;   // sWco

    cvt.s64.s32 %rd23, %r12;
    cvt.s64.s32 %rd24, %r13;
    mul.lo.s64 %rd25, %rd23, %rd24;   // sYd
    cvt.s64.s32 %rd26, %r11;
    mul.lo.s64 %rd27, %rd26, %rd25;   // sYc
    cvt.s64.s32 %rd28, %r6;
    mul.lo.s64 %rd29, %rd28, %rd27;   // sYn

    cvt.s64.s32 %rd30, %r27;
    mul.lo.s64 %rd31, %rd30, %rd17;   // xBaseN

    cvt.s64.s32 %rd32, %r28;
    mul.lo.s64 %rd33, %rd32, %rd22;   // wBaseCo

    // patch geometry (covers halo for all kh/kw across the whole tile)
    sub.s32 %r31, %r22, 1;        // TILE_H - 1
    mul.lo.s32 %r32, %r31, %r8;   // (TILE_H-1)*stride
    sub.s32 %r33, %r7, 1;         // K - 1
    mul.lo.s32 %r34, %r33, %r10;  // (K-1)*dilation
    add.s32 %r35, %r32, %r34;
    add.s32 %r36, %r35, 1;        // S (square patch side)
    mul.lo.s32 %r37, %r36, %r36;  // patch_size = S*S

    mul.lo.s32 %r38, %r19, %r22;  // ctaid.y*TILE_H
    mul.lo.s32 %r39, %r38, %r8;
    sub.s32 %r40, %r39, %r9;      // base_ih

    mul.lo.s32 %r41, %r18, %r21;  // ctaid.x*TILE_W
    mul.lo.s32 %r42, %r41, %r8;
    sub.s32 %r43, %r42, %r9;      // base_iw

    mad.lo.s32 %r44, %r17, %r21, %r16;  // tid_linear = ty*16+tx

    mov.u32 %r45, 0;   // cin_local
L_CIN_LOOP:
    setp.ge.s32 %p5, %r45, %r14;
    @%p5 bra L_CIN_DONE;

    add.s32 %r46, %r30, %r45;         // cin

    cvt.s64.s32 %rd34, %r46;
    mul.lo.s64 %rd35, %rd34, %rd15;
    add.s64 %rd36, %rd31, %rd35;      // xBaseC

    cvt.s64.s32 %rd37, %r45;
    mul.lo.s64 %rd38, %rd37, %rd20;
    add.s64 %rd39, %rd33, %rd38;      // wBaseCin

    mov.u32 %r47, 0;   // kd
L_KD_LOOP:
    setp.ge.s32 %p6, %r47, %r7;
    @%p6 bra L_KD_DONE;

    mul.lo.s32 %r48, %r26, %r8;       // od*stride
    sub.s32 %r49, %r48, %r9;          // od*stride - padding
    mul.lo.s32 %r50, %r47, %r10;      // kd*dilation
    add.s32 %r51, %r49, %r50;         // id

    setp.lt.s32 %p7, %r51, 0;
    setp.ge.s32 %p8, %r51, %r3;
    or.pred  %p9, %p7, %p8;           // invalid id (uniform across CTA)
    @%p9 bra L_KD_CONTINUE;

    cvt.s64.s32 %rd40, %r51;
    mul.lo.s64 %rd41, %rd40, %rd13;
    add.s64 %rd42, %rd36, %rd41;      // xBaseD

    cvt.s64.s32 %rd43, %r47;
    mul.lo.s64 %rd44, %rd43, %rd19;
    add.s64 %rd45, %rd39, %rd44;      // wBaseKd

    mov.u32 %r52, %r44;               // pos = tid_linear
L_LOAD_LOOP:
    setp.ge.s32 %p10, %r52, %r37;
    @%p10 bra L_LOAD_DONE;

    div.s32 %r53, %r52, %r36;         // prow
    rem.s32 %r54, %r52, %r36;         // pcol
    add.s32 %r55, %r40, %r53;         // ih
    add.s32 %r56, %r43, %r54;         // iw

    setp.lt.s32 %p11, %r55, 0;
    setp.ge.s32 %p12, %r55, %r4;
    or.pred  %p13, %p11, %p12;
    setp.lt.s32 %p14, %r56, 0;
    setp.ge.s32 %p15, %r56, %r5;
    or.pred  %p16, %p14, %p15;
    or.pred  %p17, %p13, %p16;        // invalid_load

    mov.f32 %f2, 0f00000000;
    @%p17 bra L_LOAD_STORE;

    mul.wide.s32 %rd46, %r55, %r5;    // ih*Win
    cvt.s64.s32 %rd47, %r56;
    add.s64 %rd48, %rd46, %rd47;
    add.s64 %rd49, %rd48, %rd42;      // + xBaseD
    shl.b64 %rd50, %rd49, 2;
    add.s64 %rd51, %rd5, %rd50;
    ld.global.f32 %f2, [%rd51];

L_LOAD_STORE:
    mov.u32 %r57, smem;
    mul.lo.s32 %r58, %r52, 4;
    add.s32 %r59, %r57, %r58;
    st.shared.f32 [%r59], %f2;

    add.s32 %r52, %r52, 256;
    bra L_LOAD_LOOP;
L_LOAD_DONE:
    bar.sync 0;

    @!%p3 bra L_SKIP_COMPUTE;

    mov.u32 %r60, 0;   // kh
L_KH_LOOP:
    setp.ge.s32 %p18, %r60, %r7;
    @%p18 bra L_KH_DONE;

    mul.lo.s32 %r61, %r60, %r10;      // kh*dilation
    mad.lo.s32 %r62, %r17, %r8, %r61; // srow = ty*stride + kh*dilation

    cvt.s64.s32 %rd52, %r60;
    mul.lo.s64 %rd53, %rd52, %rd18;   // kh*K
    add.s64 %rd54, %rd45, %rd53;      // wBaseKh

    mov.u32 %r63, 0;   // kw
L_KW_LOOP:
    setp.ge.s32 %p19, %r63, %r7;
    @%p19 bra L_KW_DONE;

    mul.lo.s32 %r64, %r63, %r10;      // kw*dilation
    mad.lo.s32 %r65, %r16, %r8, %r64; // scol = tx*stride + kw*dilation

    mad.lo.s32 %r66, %r62, %r36, %r65; // sidx = srow*S + scol
    mov.u32 %r67, smem;
    mul.lo.s32 %r68, %r66, 4;
    add.s32 %r69, %r67, %r68;
    ld.shared.f32 %f3, [%r69];

    cvt.s64.s32 %rd55, %r63;
    add.s64 %rd56, %rd54, %rd55;      // wIdx
    shl.b64 %rd57, %rd56, 2;
    add.s64 %rd58, %rd6, %rd57;
    ld.global.f32 %f4, [%rd58];

    fma.rn.f32 %f1, %f3, %f4, %f1;

    add.s32 %r63, %r63, 1;
    bra L_KW_LOOP;
L_KW_DONE:

    add.s32 %r60, %r60, 1;
    bra L_KH_LOOP;
L_KH_DONE:

L_SKIP_COMPUTE:
    bar.sync 0;

L_KD_CONTINUE:
    add.s32 %r47, %r47, 1;
    bra L_KD_LOOP;
L_KD_DONE:

    add.s32 %r45, %r45, 1;
    bra L_CIN_LOOP;
L_CIN_DONE:

    @!%p3 bra L_RETURN;

    cvt.s64.s32 %rd60, %r27;
    mul.lo.s64 %rd61, %rd60, %rd29;   // n*sYn
    cvt.s64.s32 %rd62, %r28;
    mul.lo.s64 %rd63, %rd62, %rd27;   // co*sYc
    add.s64 %rd64, %rd61, %rd63;

    cvt.s64.s32 %rd65, %r26;
    mul.lo.s64 %rd66, %rd65, %rd25;   // od*sYd
    add.s64 %rd67, %rd64, %rd66;

    cvt.s64.s32 %rd68, %r24;
    mul.lo.s64 %rd69, %rd68, %rd24;   // oh*Wout
    add.s64 %rd70, %rd67, %rd69;

    cvt.s64.s32 %rd71, %r23;
    add.s64 %rd72, %rd70, %rd71;      // + ow

    shl.b64 %rd73, %rd72, 2;
    add.s64 %rd74, %rd7, %rd73;
    st.global.f32 [%rd74], %f1;

L_RETURN:
    ret;
}
"""

_ENTRY_NAME = "conv3d_kernel"
_module_cache = None

_TILE_H = 16
_TILE_W = 16


def _get_module() -> PtxModule:
    global _module_cache
    if _module_cache is None:
        _module_cache = PtxModule(PTX_SOURCE)
    return _module_cache


def validate_generated_code() -> bool:
    """Compiles/loads the PTX module and verifies the entry point exists."""
    module = _get_module()
    fn = module.function(_ENTRY_NAME)
    if fn is None:
        raise RuntimeError(f"entry point '{_ENTRY_NAME}' not found in PTX module")
    return True


class ModelNew(nn.Module):
    """
    Standard 3D convolution with square kernel, implemented with a
    hand-authored PTX kernel using CTA-level (H,W) spatial output tiling and
    shared-memory staging of the reusable input tile, launched via
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 is supported"
        assert x.dim() == 5, "input must be [N, C, D, H, W]"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, D, H, Win = x_c.shape
        Cout, Cin_per_group, K, K2, K3 = w_c.shape
        assert K == K2 == K3, "kernel must be cubic"
        assert Cin % self.groups == 0 and Cout % self.groups == 0
        assert Cin // self.groups == Cin_per_group

        stride, padding, dilation = self.stride, self.padding, self.dilation
        Cout_per_group = Cout // self.groups

        Dout = (D + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid output size computed"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            b_ptr = int(b_c.data_ptr())
        else:
            b_c = None
            b_ptr = 0

        grid_x = (Wout + _TILE_W - 1) // _TILE_W
        grid_y = (Hout + _TILE_H - 1) // _TILE_H
        grid_z = N * Cout * Dout

        module = _get_module()
        fn = module.function(_ENTRY_NAME)

        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            fn,
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(int(_TILE_W), int(_TILE_H), 1),
            args=[
                u64(int(x_c.data_ptr())),
                u64(int(w_c.data_ptr())),
                u64(b_ptr),
                u64(int(y.data_ptr())),
                i32(int(N)),
                i32(int(Cin)),
                i32(int(D)),
                i32(int(H)),
                i32(int(Win)),
                i32(int(Cout)),
                i32(int(K)),
                i32(int(stride)),
                i32(int(padding)),
                i32(int(dilation)),
                i32(int(Dout)),
                i32(int(Hout)),
                i32(int(Wout)),
                i32(int(Cin_per_group)),
                i32(int(Cout_per_group)),
            ],
            stream=stream,
        )

        return y

