import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a direct (non-tiled) 3D convolution.
# Each thread computes exactly one output element:
#   idx -> (n, co, od, oh, ow)
# and accumulates over (cin_local, kd, kh, kw) with bounds checking for
# padding, exactly matching the semantics of the reference CuTe/CUDA kernel
# (nn.Conv3d forward, float32, optional bias, groups support).
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry conv3d_kernel(
    .param .u64 param_x,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_y,
    .param .u32 param_N,
    .param .u32 param_Cin,
    .param .u32 param_D,
    .param .u32 param_H,
    .param .u32 param_Win,
    .param .u32 param_Cout,
    .param .u32 param_K,
    .param .u32 param_stride,
    .param .u32 param_padding,
    .param .u32 param_dilation,
    .param .u32 param_Dout,
    .param .u32 param_Hout,
    .param .u32 param_Wout,
    .param .u32 param_CinPerGroup,
    .param .u32 param_CoutPerGroup
)
{
    .reg .pred %p<24>;
    .reg .b32  %r<70>;
    .reg .b64  %rd<90>;
    .reg .f32  %f<8>;

    ld.param.u64 %rd1, [param_x];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_y];

    ld.param.u32 %r1,  [param_N];
    ld.param.u32 %r2,  [param_Cin];
    ld.param.u32 %r3,  [param_D];
    ld.param.u32 %r4,  [param_H];
    ld.param.u32 %r5,  [param_Win];
    ld.param.u32 %r6,  [param_Cout];
    ld.param.u32 %r7,  [param_K];
    ld.param.u32 %r8,  [param_stride];
    ld.param.u32 %r9,  [param_padding];
    ld.param.u32 %r10, [param_dilation];
    ld.param.u32 %r11, [param_Dout];
    ld.param.u32 %r12, [param_Hout];
    ld.param.u32 %r13, [param_Wout];
    ld.param.u32 %r14, [param_CinPerGroup];
    ld.param.u32 %r15, [param_CoutPerGroup];

    cvta.to.global.u64 %rd5, %rd1;   // Xg
    cvta.to.global.u64 %rd6, %rd2;   // Wg
    cvta.to.global.u64 %rd7, %rd4;   // Yg
    cvta.to.global.u64 %rd8, %rd3;   // Bg (unused if bias absent)

    mov.u32 %r16, %ctaid.x;
    mov.u32 %r17, %ntid.x;
    mov.u32 %r18, %tid.x;
    mad.lo.s32 %r19, %r16, %r17, %r18;   // flat output index

    mul.lo.s32 %r20, %r6, %r11;
    mul.lo.s32 %r21, %r20, %r12;
    mul.lo.s32 %r22, %r21, %r13;
    mul.lo.s32 %r23, %r22, %r1;          // total = N*Cout*Dout*Hout*Wout

    setp.ge.s32 %p1, %r19, %r23;
    @%p1 bra L_RETURN;

    div.s32 %r24, %r19, %r13;
    rem.s32 %r25, %r19, %r13;            // ow
    div.s32 %r26, %r24, %r12;
    rem.s32 %r27, %r24, %r12;            // oh
    div.s32 %r28, %r26, %r11;
    rem.s32 %r29, %r26, %r11;            // od
    div.s32 %r30, %r28, %r6;             // n
    rem.s32 %r31, %r28, %r6;             // co

    div.s32 %r32, %r31, %r15;            // group
    mul.lo.s32 %r33, %r32, %r14;         // cin_start

    mov.f32 %f1, 0f00000000;
    setp.eq.s64 %p2, %rd3, 0;
    @%p2 bra L_BIAS_DONE;
    mul.wide.s32 %rd9, %r31, 4;
    add.s64 %rd10, %rd8, %rd9;
    ld.global.f32 %f1, [%rd10];
L_BIAS_DONE:

    cvt.s64.s32 %rd11, %r4;
    cvt.s64.s32 %rd12, %r5;
    mul.lo.s64 %rd13, %rd11, %rd12;      // sXd = H*Win
    cvt.s64.s32 %rd14, %r3;
    mul.lo.s64 %rd15, %rd14, %rd13;      // sXc = D*H*Win
    cvt.s64.s32 %rd16, %r2;
    mul.lo.s64 %rd17, %rd16, %rd15;      // sXn = Cin*D*H*Win

    cvt.s64.s32 %rd18, %r7;
