    module = _get_module()
    fn = module.function(_ENTRY_NAME)
    if fn is None:
        raise RuntimeError(f"entry point '{_ENTRY_NAME}' not found in PTX module")
    return True


class ModelNew(nn.Module):
    """
    Standard 3D convolution with square kernel, implemented with a
    hand-authored PTX kernel (one thread per output element) launched via
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 is supported"
        assert x.dim() == 5, "input must be [N, C, D, H, W]"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, D, H, Win = x_c.shape
        Cout, Cin_per_group, K, K2, K3 = w_c.shape
        assert K == K2 == K3, "kernel must be cubic"
        assert Cin % self.groups == 0 and Cout % self.groups == 0
        assert Cin // self.groups == Cin_per_group

        stride, padding, dilation = self.stride, self.padding, self.dilation
        Cout_per_group = Cout // self.groups

        Dout = (D + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid output size computed"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            b_ptr = int(b_c.data_ptr())
        else:
            b_c = None
            b_ptr = 0

        total_out = N * Cout * Dout * Hout * Wout
        block_x = 256
        grid_x = (total_out + block_x - 1) // block_x

        module = _get_module()
        fn = module.function(_ENTRY_NAME)

        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            fn,
            grid=(int(grid_x), 1, 1),
            block=(int(block_x), 1, 1),
            args=[
                u64(int(x_c.data_ptr())),
                u64(int(w_c.data_ptr())),
                u64(b_ptr),
                u64(int(y.data_ptr())),
                i32(int(N)),
                i32(int(Cin)),
                i32(int(D)),
                i32(int(H)),
                i32(int(Win)),
                i32(int(Cout)),
                i32(int(K)),
                i32(int(stride)),
                i32(int(padding)),
                i32(int(dilation)),
                i32(int(Dout)),
                i32(int(Hout)),
                i32(int(Wout)),
                i32(int(Cin_per_group)),
                i32(int(Cout_per_group)),
            ],
            stream=stream,
        )

        return y

