    mul.lo.s32 %r45, %r7, %r7;       // K*K
    mul.lo.s32 %r46, %r45, %r7;      // K*K*K
    mul.lo.s32 %r47, %r46, %r14;     // *CinPerGroup
    mul.lo.s32 %r48, %r47, %r15;     // total_w = CoutPerGroup*CinPerGroup*K^3

