class ModelNew(nn.Module):
    """
    Standard 3D convolution with square kernel, implemented with a
    hand-authored, CTA-tiled PTX kernel that stages the required input
    receptive-field patch and the group's weight tile into shared memory
    once per CTA, and reuses them across all output channels of the group
    and across all spatial output positions handled by the CTA.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 is supported"
        assert x.dim() == 5, "input must be [N, C, D, H, W]"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, D, H, Win = x_c.shape
        Cout, Cin_per_group, K, K2, K3 = w_c.shape
        assert K == K2 == K3, "kernel must be cubic"
        assert Cin % self.groups == 0 and Cout % self.groups == 0
        assert Cin // self.groups == Cin_per_group

        stride, padding, dilation = self.stride, self.padding, self.dilation
        Cout_per_group = Cout // self.groups

        Dout = (D + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid output size computed"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            b_ptr = int(b_c.data_ptr())
        else:
            b_c = None
            b_ptr = 0

        PH = (_TILE_H - 1) * stride + (K - 1) * dilation + 1
        PW = (_TILE_W - 1) * stride + (K - 1) * dilation + 1

        shared_elems = (Cin_per_group * K * PH * PW) + (Cout_per_group * Cin_per_group * K * K * K)
        shared_bytes = shared_elems * 4
        assert shared_bytes <= _SMEM_BYTES_LIMIT, (
            f"shared memory requirement ({shared_bytes} bytes) exceeds the static "
            f"budget ({_SMEM_BYTES_LIMIT} bytes) for this convolution configuration"
        )

        grid_x = (Wout + _TILE_W - 1) // _TILE_W
        grid_y = (Hout + _TILE_H - 1) // _TILE_H
        grid_z = N * Dout * self.groups

        block = (_TILE_H * _TILE_W, 1, 1)

        module = _get_module()
        fn = module.function(_ENTRY_NAME)

        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            fn,
            (int(grid_x), int(grid_y), int(grid_z)),
            block,
            [
                u64(int(x_c.data_ptr())),
                u64(int(w_c.data_ptr())),
                u64(b_ptr),
                u64(int(y.data_ptr())),
                i32(int(N)),
                i32(int(Cin)),
                i32(int(D)),
                i32(int(H)),
                i32(int(Win)),
                i32(int(Cout)),
                i32(int(K)),
                i32(int(stride)),
                i32(int(padding)),
                i32(int(dilation)),
                i32(int(Dout)),
                i32(int(Hout)),
                i32(int(Wout)),
                i32(int(Cin_per_group)),
                i32(int(Cout_per_group)),
                i32(int(self.groups)),
                i32(int(PH)),
                i32(int(PW)),
            ],
        )

        return y

import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a *tiled* 3D convolution.
#
# Structural rewrite vs. the naive one-thread-per-output kernel:
#   - Each CTA is responsible for a fixed (n, od, group) and an (TILE_H x
#     TILE_W) tile of output (oh, ow) positions (TILE_H = TILE_W = 8, 64
#     threads per CTA).
#   - The CTA cooperatively stages the required input receptive-field patch
#     (covering the whole spatial tile, all depth-kernel offsets, and all
#     input channels of the group) into shared memory ONCE.
#   - The CTA also cooperatively stages the ENTIRE weight tile for its group
#     (all output channels of the group) into shared memory ONCE.
#   - Every thread then loops over all output channels of the group,
#     reusing the shared-memory input tile (reused across output channels)
#     and the shared-memory weight tile (reused across all spatial threads
#     in the CTA), which drastically cuts down redundant global memory
#     traffic compared to the direct per-output-element kernel.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.shared .align 4 .b8 smem[24576];

.visible .entry conv3d_kernel(
    .param .u64 param_x,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_y,
    .param .u32 param_N,
    .param .u32 param_Cin,
    .param .u32 param_D,
    .param .u32 param_H,
    .param .u32 param_Win,
    .param .u32 param_Cout,
    .param .u32 param_K,
    .param .u32 param_stride,
    .param .u32 param_padding,
    .param .u32 param_dilation,
    .param .u32 param_Dout,
    .param .u32 param_Hout,
    .param .u32 param_Wout,
    .param .u32 param_CinPerGroup,
    .param .u32 param_CoutPerGroup,
    .param .u32 param_groups,
    .param .u32 param_PH,
    .param .u32 param_PW
)
{
    .reg .pred %p<40>;
    .reg .b32  %r<200>;
    .reg .b64  %rd<100>;
    .reg .f32  %f<20>;

    ld.param.u64 %rd1, [param_x];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_y];

    ld.param.u32 %r1,  [param_N];
    ld.param.u32 %r2,  [param_Cin];
    ld.param.u32 %r3,  [param_D];
    ld.param.u32 %r4,  [param_H];
    ld.param.u32 %r5,  [param_Win];
    ld.param.u32 %r6,  [param_Cout];
    ld.param.u32 %r7,  [param_K];
    ld.param.u32 %r8,  [param_stride];
    ld.param.u32 %r9,  [param_padding];
    ld.param.u32 %r10, [param_dilation];
    ld.param.u32 %r11, [param_Dout];
    ld.param.u32 %r12, [param_Hout];
    ld.param.u32 %r13, [param_Wout];
    ld.param.u32 %r14, [param_CinPerGroup];
    ld.param.u32 %r15, [param_CoutPerGroup];
    ld.param.u32 %r16, [param_groups];
    ld.param.u32 %r17, [param_PH];
    ld.param.u32 %r18, [param_PW];

    cvta.to.global.u64 %rd5, %rd1;   // Xg
    cvta.to.global.u64 %rd6, %rd2;   // Wg
    cvta.to.global.u64 %rd7, %rd4;   // Yg
    cvta.to.global.u64 %rd8, %rd3;   // Bg

    mov.u32 %r19, smem;              // shared mem base address

    mov.u32 %r20, %tid.x;            // tid (0..63)
    shr.u32 %r21, %r20, 3;           // th = tid >> 3
    and.b32  %r22, %r20, 7;          // tw = tid & 7

    mov.u32 %r23, %ctaid.x;          // bx
    mov.u32 %r24, %ctaid.y;          // by
    mov.u32 %r25, %ctaid.z;          // bz

    rem.s32 %r26, %r25, %r16;        // group = bz % groups
    div.s32 %r27, %r25, %r16;        // tmp   = bz / groups
    rem.s32 %r28, %r27, %r11;        // od    = tmp % Dout
    div.s32 %r29, %r27, %r11;        // n     = tmp / Dout

    mul.lo.s32 %r30, %r26, %r14;     // cin_start = group*CinPerGroup
    mul.lo.s32 %r31, %r26, %r15;     // co_start  = group*CoutPerGroup

    mul.lo.s32 %r32, %r24, 8;        // oh_tile_start = by*8
    mul.lo.s32 %r33, %r23, 8;        // ow_tile_start = bx*8

    mul.lo.s32 %r34, %r32, %r8;
    sub.s32 %r35, %r34, %r9;         // base_h
    mul.lo.s32 %r36, %r33, %r8;
    sub.s32 %r37, %r36, %r9;         // base_w

    mul.lo.s32 %r38, %r28, %r8;
    sub.s32 %r39, %r38, %r9;         // id_base = od*stride - padding

    add.s32 %r40, %r32, %r21;        // oh
    add.s32 %r41, %r33, %r22;        // ow

    setp.lt.s32 %p1, %r40, %r12;     // oh < Hout
    setp.lt.s32 %p2, %r41, %r13;     // ow < Wout
    and.pred  %p3, %p1, %p2;         // valid output thread

    mul.lo.s32 %r42, %r17, %r18;     // PH*PW
    mul.lo.s32 %r43, %r42, %r7;      // *K
    mul.lo.s32 %r44, %r43, %r14;     // total_x = CinPerGroup*K*PH*PW

    mul.lo.s32 %r45, %r7, %r7;       // K*K
    mul.lo.s32 %r46, %r45, %r7;      // K*K*K
    mul.lo.s32 %r47, %r46, %r14;     // *CinPerGroup
    mul.lo.s32 %r48, %r47, %r15;     // total_w = CoutPerGroup*CinPerGroup*K^3

    shl.b32 %r49, %r44, 2;           // total_x*4 bytes
    add.s32 %r50, %r19, %r49;        // smem_w base address

    // ---------------- load input tile into shared memory ----------------
    mov.u32 %r51, %r20;              // idx = tid
L_LOAD_X:
    setp.ge.s32 %p4, %r51, %r44;
    @%p4 bra L_LOAD_X_DONE;

    rem.s32 %r52, %r51, %r18;        // pw
    div.s32 %r53, %r51, %r18;        // t1
    rem.s32 %r54, %r53, %r17;        // ph
    div.s32 %r55, %r53, %r17;        // t2
    rem.s32 %r56, %r55, %r7;         // kd
    div.s32 %r57, %r55, %r7;         // cin_local

    add.s32 %r58, %r35, %r54;        // ih
    add.s32 %r59, %r37, %r52;        // iw
    mul.lo.s32 %r160, %r56, %r10;    // kd*dilation
    add.s32 %r60, %r39, %r160;       // id = id_base + kd*dilation
    add.s32 %r61, %r30, %r57;        // cin

    setp.lt.s32 %p5, %r60, 0;
    setp.ge.s32 %p6, %r60, %r3;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r58, 0;
    setp.ge.s32 %p9, %r58, %r4;
    or.pred  %p10, %p8, %p9;
    or.pred  %p11, %p7, %p10;
    setp.lt.s32 %p12, %r59, 0;
    setp.ge.s32 %p13, %r59, %r5;
    or.pred  %p14, %p12, %p13;
    or.pred  %p15, %p11, %p14;       // out-of-bounds

    mov.f32 %f1, 0f00000000;
    @%p15 bra L_LOAD_X_STORE;

    mul.lo.s32 %r62, %r29, %r2;      // n*Cin
    add.s32 %r63, %r62, %r61;        // ncin = n*Cin + cin

    cvt.s64.s32 %rd11, %r63;
    cvt.s64.s32 %rd12, %r3;          // D
    cvt.s64.s32 %rd13, %r4;          // H
    cvt.s64.s32 %rd14, %r5;          // Win
    mul.lo.s64 %rd15, %rd13, %rd14;  // H*Win
    mul.lo.s64 %rd16, %rd11, %rd12;  // ncin*D
    cvt.s64.s32 %rd17, %r60;         // id
    add.s64 %rd18, %rd16, %rd17;     // ncin*D + id
    mul.lo.s64 %rd19, %rd18, %rd15;  // (ncin*D+id)*H*Win
    cvt.s64.s32 %rd20, %r58;         // ih
    mul.lo.s64 %rd21, %rd20, %rd14;  // ih*Win
    add.s64 %rd22, %rd19, %rd21;
    cvt.s64.s32 %rd23, %r59;         // iw
    add.s64 %rd24, %rd22, %rd23;

    shl.b64 %rd25, %rd24, 2;
    add.s64 %rd26, %rd5, %rd25;
    ld.global.f32 %f1, [%rd26];

L_LOAD_X_STORE:
    shl.b32 %r65, %r51, 2;
    add.s32 %r66, %r19, %r65;
    st.shared.f32 [%r66], %f1;

    add.s32 %r51, %r51, 64;
    bra L_LOAD_X;
L_LOAD_X_DONE:

    // ---------------- load weight tile into shared memory ----------------
    mov.u32 %r70, %r20;              // idx = tid
L_LOAD_W:
    setp.ge.s32 %p16, %r70, %r48;
    @%p16 bra L_LOAD_W_DONE;

    rem.s32 %r71, %r70, %r7;         // kw
    div.s32 %r72, %r70, %r7;         // t1
    rem.s32 %r73, %r72, %r7;         // kh
    div.s32 %r74, %r72, %r7;         // t2
    rem.s32 %r75, %r74, %r7;         // kd
    div.s32 %r76, %r74, %r7;         // t3
    rem.s32 %r77, %r76, %r14;        // cin_local
    div.s32 %r78, %r76, %r14;        // co_local

    add.s32 %r79, %r31, %r78;        // co = co_start + co_local

    mul.lo.s32 %r80, %r79, %r14;
    add.s32 %r81, %r80, %r77;
    mul.lo.s32 %r82, %r81, %r7;
    add.s32 %r83, %r82, %r75;
    mul.lo.s32 %r84, %r83, %r7;
    add.s32 %r85, %r84, %r73;
    mul.lo.s32 %r86, %r85, %r7;
    add.s32 %r87, %r86, %r71;        // weight flat index

    cvt.s64.s32 %rd30, %r87;
    shl.b64 %rd31, %rd30, 2;
    add.s64 %rd32, %rd6, %rd31;
    ld.global.f32 %f2, [%rd32];

    shl.b32 %r88, %r70, 2;
    add.s32 %r89, %r50, %r88;
    st.shared.f32 [%r89], %f2;

    add.s32 %r70, %r70, 64;
    bra L_LOAD_W;
L_LOAD_W_DONE:

    bar.sync 0;

    @!%p3 bra L_SKIP_COMPUTE;

    setp.eq.s64 %p20, %rd3, 0;       // no bias

    mov.u32 %r90, 0;                 // co_local = 0
L_COLOOP:
    setp.ge.s32 %p21, %r90, %r15;
    @%p21 bra L_COLOOP_DONE;

    mov.f32 %f10, 0f00000000;
    add.s32 %r91, %r31, %r90;        // co

    @%p20 bra L_BIAS_SKIP2;
    cvt.s64.s32 %rd40, %r91;
    shl.b64 %rd41, %rd40, 2;
    add.s64 %rd42, %rd8, %rd41;
    ld.global.f32 %f10, [%rd42];
L_BIAS_SKIP2:

    mov.u32 %r92, 0;                 // cin_local = 0
L_CINLOOP:
    setp.ge.s32 %p22, %r92, %r14;
    @%p22 bra L_CINLOOP_DONE;

    mov.u32 %r93, 0;                 // kd = 0
L_KDLOOP:
    setp.ge.s32 %p23, %r93, %r7;
    @%p23 bra L_KDLOOP_DONE;

    mov.u32 %r94, 0;                 // kh = 0
L_KHLOOP:
    setp.ge.s32 %p24, %r94, %r7;
    @%p24 bra L_KHLOOP_DONE;

    mul.lo.s32 %r95, %r21, %r8;
    mul.lo.s32 %r96, %r94, %r10;
    add.s32 %r97, %r95, %r96;        // ph

    mov.u32 %r98, 0;                 // kw = 0
L_KWLOOP:
    setp.ge.s32 %p25, %r98, %r7;
    @%p25 bra L_KWLOOP_DONE;

    mul.lo.s32 %r99, %r22, %r8;
    mul.lo.s32 %r100, %r98, %r10;
    add.s32 %r101, %r99, %r100;      // pw

    mul.lo.s32 %r102, %r92, %r7;
    add.s32 %r103, %r102, %r93;
    mul.lo.s32 %r104, %r103, %r17;
    add.s32 %r105, %r104, %r97;
    mul.lo.s32 %r106, %r105, %r18;
    add.s32 %r107, %r106, %r101;     // xidx

    shl.b32 %r108, %r107, 2;
    add.s32 %r109, %r19, %r108;
    ld.shared.f32 %f11, [%r109];

    mul.lo.s32 %r110, %r90, %r14;
    add.s32 %r111, %r110, %r92;
    mul.lo.s32 %r112, %r111, %r7;
    add.s32 %r113, %r112, %r93;
    mul.lo.s32 %r114, %r113, %r7;
    add.s32 %r115, %r114, %r94;
    mul.lo.s32 %r116, %r115, %r7;
    add.s32 %r117, %r116, %r98;      // widx

    shl.b32 %r118, %r117, 2;
    add.s32 %r119, %r50, %r118;
    ld.shared.f32 %f12, [%r119];

    fma.rn.f32 %f10, %f11, %f12, %f10;

    add.s32 %r98, %r98, 1;
    bra L_KWLOOP;
L_KWLOOP_DONE:

    add.s32 %r94, %r94, 1;
    bra L_KHLOOP;
L_KHLOOP_DONE:

    add.s32 %r93, %r93, 1;
    bra L_KDLOOP;
L_KDLOOP_DONE:

    add.s32 %r92, %r92, 1;
    bra L_CINLOOP;
L_CINLOOP_DONE:

    mul.lo.s32 %r120, %r29, %r6;
    add.s32 %r121, %r120, %r91;      // n*Cout + co
    cvt.s64.s32 %rd50, %r121;
    cvt.s64.s32 %rd51, %r11;         // Dout
    cvt.s64.s32 %rd52, %r12;         // Hout
    cvt.s64.s32 %rd53, %r13;         // Wout
    mul.lo.s64 %rd54, %rd50, %rd51;
    cvt.s64.s32 %rd55, %r28;         // od
    add.s64 %rd56, %rd54, %rd55;
    mul.lo.s64 %rd57, %rd56, %rd52;
    cvt.s64.s32 %rd58, %r40;         // oh
    add.s64 %rd59, %rd57, %rd58;
    mul.lo.s64 %rd60, %rd59, %rd53;
    cvt.s64.s32 %rd61, %r41;         // ow
    add.s64 %rd62, %rd60, %rd61;

    shl.b64 %rd63, %rd62, 2;
    add.s64 %rd64, %rd7, %rd63;
    st.global.f32 [%rd64], %f10;

    add.s32 %r90, %r90, 1;
    bra L_COLOOP;
L_COLOOP_DONE:

L_SKIP_COMPUTE:
    ret;
}
"""

_ENTRY_NAME = "conv3d_kernel"
_module_cache = None

_TILE_H = 8
_TILE_W = 8
_SMEM_BYTES_LIMIT = 24576


def _get_module() -> PtxModule:
    global _module_cache
    if _module_cache is None:
        _module_cache = PtxModule(PTX_SOURCE)
    return _module_cache


def validate_generated_code() -> bool:
    """Compiles/loads the PTX module and verifies the entry point exists."""
    module = _get_module()
    fn = module.function(_ENTRY_NAME)
    if fn is None:
        raise RuntimeError(f"entry point '{_ENTRY_NAME}' not found in PTX module")
    return True


class ModelNew(nn.Module):
    """
    Standard 3D convolution with square kernel, implemented with a
    hand-authored, CTA-tiled PTX kernel that stages the required input
    receptive-field patch and the group's weight tile into shared memory
    once per CTA, and reuses them across all output channels of the group
    and across all spatial output positions handled by the CTA.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 is supported"
        assert x.dim() == 5, "input must be [N, C, D, H, W]"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, D, H, Win = x_c.shape
        Cout, Cin_per_group, K, K2, K3 = w_c.shape
        assert K == K2 == K3, "kernel must be cubic"
        assert Cin % self.groups == 0 and Cout % self.groups == 0
        assert Cin // self.groups == Cin_per_group

        stride, padding, dilation = self.stride, self.padding, self.dilation
        Cout_per_group = Cout // self.groups

        Dout = (D + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid output size computed"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            b_ptr = int(b_c.data_ptr())
        else:
            b_c = None
            b_ptr = 0

        PH = (_TILE_H - 1) * stride + (K - 1) * dilation + 1
        PW = (_TILE_W - 1) * stride + (K - 1) * dilation + 1

        shared_elems = (Cin_per_group * K * PH * PW) + (Cout_per_group * Cin_per_group * K * K * K)
        shared_bytes = shared_elems * 4
        assert shared_bytes <= _SMEM_BYTES_LIMIT, (
            f"shared memory requirement ({shared_bytes} bytes) exceeds the static "
            f"budget ({_SMEM_BYTES_LIMIT} bytes) for this convolution configuration"
        )

        grid_x = (Wout + _TILE_W - 1) // _TILE_W
        grid_y = (Hout + _TILE_H - 1) // _TILE_H
        grid_z = N * Dout * self.groups

        block = (_TILE_H * _TILE_W, 1, 1)

        module = _get_module()
        fn = module.function(_ENTRY_NAME)

        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            fn,
            (int(grid_x), int(grid_y), int(grid_z)),
            block,
            [
            (
                u64(int(w_c.data_ptr())),
                u64(b_ptr),
                u64(int(y.data_ptr())),
                i32(int(N)),
                i32(int(Cin)),
                i32(int(D)),
                i32(int(H)),
                i32(int(Win)),
                i32(int(Cout)),
                i32(int(K)),
                i32(int(stride)),
                i32(int(padding)),
                i32(int(dilation)),
                i32(int(Dout)),
                i32(int(Hout)),
                i32(int(Wout)),
                i32(int(Cin_per_group)),
                i32(int(Cout_per_group)),
                i32(int(self.groups)),
                i32(int(PH)),
                i32(int(PW)),
            ],
            ),

        return y

import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a *tiled* 3D convolution.
#
# Structural rewrite vs. the naive one-thread-per-output kernel:
#   - Each CTA is responsible for a fixed (n, od, group) and an (TILE_H x
#     TILE_W) tile of output (oh, ow) positions (TILE_H = TILE_W = 8, 64
#     threads per CTA).
#   - The CTA cooperatively stages the required input receptive-field patch
#     (covering the whole spatial tile, all depth-kernel offsets, and all
#     input channels of the group) into shared memory ONCE.
#   - The CTA also cooperatively stages the ENTIRE weight tile for its group
#     (all output channels of the group) into shared memory ONCE.
#   - Every thread then loops over all output channels of the group,
#     reusing the shared-memory input tile (reused across output channels)
#     and the shared-memory weight tile (reused across all spatial threads
#     in the CTA), which drastically cuts down redundant global memory
#     traffic compared to the direct per-output-element kernel.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.shared .align 4 .b8 smem[24576];

.visible .entry conv3d_kernel(
    .param .u64 param_x,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_y,
    .param .u32 param_N,
    .param .u32 param_Cin,
    .param .u32 param_D,
    .param .u32 param_H,
    .param .u32 param_Win,
    .param .u32 param_Cout,
    .param .u32 param_K,
    .param .u32 param_stride,
    .param .u32 param_padding,
    .param .u32 param_dilation,
    .param .u32 param_Dout,
    .param .u32 param_Hout,
    .param .u32 param_Wout,
    .param .u32 param_CinPerGroup,
    .param .u32 param_CoutPerGroup,
    .param .u32 param_groups,
    .param .u32 param_PH,
    .param .u32 param_PW
)
{
    .reg .pred %p<40>;
    .reg .b32  %r<200>;
    .reg .b64  %rd<100>;
    .reg .f32  %f<20>;

    ld.param.u64 %rd1, [param_x];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_y];

    ld.param.u32 %r1,  [param_N];
    ld.param.u32 %r2,  [param_Cin];
    ld.param.u32 %r3,  [param_D];
    ld.param.u32 %r4,  [param_H];
    ld.param.u32 %r5,  [param_Win];
    ld.param.u32 %r6,  [param_Cout];
    ld.param.u32 %r7,  [param_K];
    ld.param.u32 %r8,  [param_stride];
    ld.param.u32 %r9,  [param_padding];
    ld.param.u32 %r10, [param_dilation];
    ld.param.u32 %r11, [param_Dout];
    ld.param.u32 %r12, [param_Hout];
    ld.param.u32 %r13, [param_Wout];
    ld.param.u32 %r14, [param_CinPerGroup];
    ld.param.u32 %r15, [param_CoutPerGroup];
    ld.param.u32 %r16, [param_groups];
    ld.param.u32 %r17, [param_PH];
    ld.param.u32 %r18, [param_PW];

    cvta.to.global.u64 %rd5, %rd1;   // Xg
    cvta.to.global.u64 %rd6, %rd2;   // Wg
    cvta.to.global.u64 %rd7, %rd4;   // Yg
    cvta.to.global.u64 %rd8, %rd3;   // Bg

    mov.u32 %r19, smem;              // shared mem base address

    mov.u32 %r20, %tid.x;            // tid (0..63)
    shr.u32 %r21, %r20, 3;           // th = tid >> 3
    and.b32  %r22, %r20, 7;          // tw = tid & 7

    mov.u32 %r23, %ctaid.x;          // bx
    mov.u32 %r24, %ctaid.y;          // by
    mov.u32 %r25, %ctaid.z;          // bz

    rem.s32 %r26, %r25, %r16;        // group = bz % groups
    div.s32 %r27, %r25, %r16;        // tmp   = bz / groups
    rem.s32 %r28, %r27, %r11;        // od    = tmp % Dout
    div.s32 %r29, %r27, %r11;        // n     = tmp / Dout

    mul.lo.s32 %r30, %r26, %r14;     // cin_start = group*CinPerGroup
    mul.lo.s32 %r31, %r26, %r15;     // co_start  = group*CoutPerGroup

    mul.lo.s32 %r32, %r24, 8;        // oh_tile_start = by*8
    mul.lo.s32 %r33, %r23, 8;        // ow_tile_start = bx*8

    mul.lo.s32 %r34, %r32, %r8;
    sub.s32 %r35, %r34, %r9;         // base_h
    mul.lo.s32 %r36, %r33, %r8;
    sub.s32 %r37, %r36, %r9;         // base_w

    mul.lo.s32 %r38, %r28, %r8;
    sub.s32 %r39, %r38, %r9;         // id_base = od*stride - padding

    add.s32 %r40, %r32, %r21;        // oh
    add.s32 %r41, %r33, %r22;        // ow

    setp.lt.s32 %p1, %r40, %r12;     // oh < Hout
    setp.lt.s32 %p2, %r41, %r13;     // ow < Wout
    and.pred  %p3, %p1, %p2;         // valid output thread

    mul.lo.s32 %r42, %r17, %r18;     // PH*PW
    mul.lo.s32 %r43, %r42, %r7;      // *K
    mul.lo.s32 %r44, %r43, %r14;     // total_x = CinPerGroup*K*PH*PW

    mul.lo.s32 %r45, %r7, %r7;       // K*K
    mul.lo.s32 %r46, %r45, %r7;      // K*K*K
    mul.lo.s32 %r47, %r46, %r14;     // *CinPerGroup
    mul.lo.s32 %r48, %r47, %r15;     // total_w = CoutPerGroup*CinPerGroup*K^3

    shl.b32 %r49, %r44, 2;           // total_x*4 bytes
    add.s32 %r50, %r19, %r49;        // smem_w base address

    // ---------------- load input tile into shared memory ----------------
    mov.u32 %r51, %r20;              // idx = tid
L_LOAD_X:
    setp.ge.s32 %p4, %r51, %r44;
    @%p4 bra L_LOAD_X_DONE;

    rem.s32 %r52, %r51, %r18;        // pw
    div.s32 %r53, %r51, %r18;        // t1
    rem.s32 %r54, %r53, %r17;        // ph
    div.s32 %r55, %r53, %r17;        // t2
    rem.s32 %r56, %r55, %r7;         // kd
    div.s32 %r57, %r55, %r7;         // cin_local

    add.s32 %r58, %r35, %r54;        // ih
    add.s32 %r59, %r37, %r52;        // iw
    mul.lo.s32 %r160, %r56, %r10;    // kd*dilation
    add.s32 %r60, %r39, %r160;       // id = id_base + kd*dilation
    add.s32 %r61, %r30, %r57;        // cin

    setp.lt.s32 %p5, %r60, 0;
    setp.ge.s32 %p6, %r60, %r3;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r58, 0;
    setp.ge.s32 %p9, %r58, %r4;
    or.pred  %p10, %p8, %p9;
    or.pred  %p11, %p7, %p10;
    setp.lt.s32 %p12, %r59, 0;
    setp.ge.s32 %p13, %r59, %r5;
    or.pred  %p14, %p12, %p13;
    or.pred  %p15, %p11, %p14;       // out-of-bounds

    mov.f32 %f1, 0f00000000;
    @%p15 bra L_LOAD_X_STORE;

    mul.lo.s32 %r62, %r29, %r2;      // n*Cin
    add.s32 %r63, %r62, %r61;        // ncin = n*Cin + cin

    cvt.s64.s32 %rd11, %r63;
    cvt.s64.s32 %rd12, %r3;          // D
    cvt.s64.s32 %rd13, %r4;          // H
    cvt.s64.s32 %rd14, %r5;          // Win
    mul.lo.s64 %rd15, %rd13, %rd14;  // H*Win
    mul.lo.s64 %rd16, %rd11, %rd12;  // ncin*D
    cvt.s64.s32 %rd17, %r60;         // id
    add.s64 %rd18, %rd16, %rd17;     // ncin*D + id
    mul.lo.s64 %rd19, %rd18, %rd15;  // (ncin*D+id)*H*Win
    cvt.s64.s32 %rd20, %r58;         // ih
    mul.lo.s64 %rd21, %rd20, %rd14;  // ih*Win
    add.s64 %rd22, %rd19, %rd21;
    cvt.s64.s32 %rd23, %r59;         // iw
    add.s64 %rd24, %rd22, %rd23;

    shl.b64 %rd25, %rd24, 2;
    add.s64 %rd26, %rd5, %rd25;
    ld.global.f32 %f1, [%rd26];

L_LOAD_X_STORE:
    shl.b32 %r65, %r51, 2;
    add.s32 %r66, %r19, %r65;
    st.shared.f32 [%r66], %f1;

    add.s32 %r51, %r51, 64;
    bra L_LOAD_X;
L_LOAD_X_DONE:

    // ---------------- load weight tile into shared memory ----------------
    mov.u32 %r70, %r20;              // idx = tid
L_LOAD_W:
    setp.ge.s32 %p16, %r70, %r48;
    @%p16 bra L_LOAD_W_DONE;

