    @%p24 bra L_KHLOOP_DONE;

    mul.lo.s32 %r95, %r21, %r8;
    mul.lo.s32 %r96, %r94, %r10;
    add.s32 %r97, %r95, %r96;        // ph

    mov.u32 %r98, 0;                 // kw = 0
L_KWLOOP:
    setp.ge.s32 %p25, %r98, %r7;
