                i32(int(K)),
                i32(int(stride)),
                i32(int(padding)),
                i32(int(dilation)),
                i32(int(Dout)),
                i32(int(Hout)),
                i32(int(Wout)),
                i32(int(Cin_per_group)),
                i32(int(Cout_per_group)),
            ],
