# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a 3D convolution with CTA-level spatial
# tiling and shared-memory staging of the reusable input patch.
#
# Structural change vs. the naive "one thread per output element" kernel:
#   - Each CTA is responsible for exactly ONE spatial output location
#     (n, od, oh, ow) within ONE group.
#   - The input patch needed for that location (CinPerGroup * K * K * K
#     values) is cooperatively loaded ONCE into shared memory by the CTA's
#     threads, instead of being reloaded independently and redundantly by
#     every output-channel thread (which, in the naive kernel, re-reads the
#     same input values Cout_per_group times from global memory).
#   - Threads within the CTA then each compute one (or a strided set of)
#     output channel(s) for that spatial location, reading the shared input
#     patch and per-channel weights, accumulating the dot product, and
#     writing the result.
#
# This exploits the large output-channel reuse of the input activations
# (Cin is small, Cout is comparatively large), which is exactly the
# structural weakness of the previous direct/naive kernel.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.shared .align 4 .b8 smem_patch[16384];

.visible .entry conv3d_kernel(
    .param .u64 param_x,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_y,
    .param .u32 param_N,
    .param .u32 param_Cin,
    .param .u32 param_D,
    .param .u32 param_H,
    .param .u32 param_Win,
    .param .u32 param_Cout,
    .param .u32 param_K,
    .param .u32 param_stride,
    .param .u32 param_padding,
    .param .u32 param_dilation,
    .param .u32 param_Dout,
    .param .u32 param_Hout,
    .param .u32 param_Wout,
    .param .u32 param_CinPerGroup,
    .param .u32 param_CoutPerGroup
)
{
    .reg .pred %p<20>;
    .reg .b32  %r<100>;
    .reg .b64  %rd<90>;
    .reg .f32  %f<8>;

    ld.param.u64 %rd1, [param_x];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_y];

    ld.param.u32 %r1,  [param_N];
    ld.param.u32 %r2,  [param_Cin];
    ld.param.u32 %r3,  [param_D];
    ld.param.u32 %r4,  [param_H];
    ld.param.u32 %r5,  [param_Win];
    ld.param.u32 %r6,  [param_Cout];
    ld.param.u32 %r7,  [param_K];
    ld.param.u32 %r8,  [param_stride];
    ld.param.u32 %r9,  [param_padding];
    ld.param.u32 %r10, [param_dilation];
    ld.param.u32 %r11, [param_Dout];
    ld.param.u32 %r12, [param_Hout];
    ld.param.u32 %r13, [param_Wout];
    ld.param.u32 %r14, [param_CinPerGroup];
    ld.param.u32 %r15, [param_CoutPerGroup];

    cvta.to.global.u64 %rd5, %rd1;   // Xg
    cvta.to.global.u64 %rd6, %rd2;   // Wg
    cvta.to.global.u64 %rd7, %rd4;   // Yg
    cvta.to.global.u64 %rd8, %rd3;   // Bg (address only; may be null)

    mov.u32 %r20, %ctaid.x;   // flat spatial index within Dout*Hout*Wout
    mov.u32 %r21, %ctaid.y;   // n
    mov.u32 %r22, %ctaid.z;   // group
    mov.u32 %r23, %tid.x;
    mov.u32 %r24, %ntid.x;

    rem.s32 %r25, %r20, %r13;   // ow
    div.s32 %r26, %r20, %r13;
    rem.s32 %r27, %r26, %r12;   // oh
    div.s32 %r28, %r26, %r12;   // od

    mul.lo.s32 %r29, %r22, %r14;   // cin_start
    mul.lo.s32 %r30, %r22, %r15;   // co_start

    mul.lo.s32 %r31, %r7, %r7;     // K*K
    mul.lo.s32 %r32, %r31, %r7;    // K*K*K
    mul.lo.s32 %r33, %r32, %r14;   // patchSize = CinPerGroup*K^3

    // X strides
    cvt.s64.s32 %rd11, %r4;
    cvt.s64.s32 %rd12, %r5;
    mul.lo.s64 %rd13, %rd11, %rd12;   // sXHW = H*Win
    cvt.s64.s32 %rd14, %r3;
    mul.lo.s64 %rd15, %rd14, %rd13;   // sXDHW = D*H*Win
    cvt.s64.s32 %rd16, %r2;
    mul.lo.s64 %rd17, %rd16, %rd15;   // sXCDHW = Cin*D*H*Win
    cvt.s64.s32 %rd18, %r21;
    mul.lo.s64 %rd19, %rd18, %rd17;   // xBaseN = n*sXCDHW

    // Y strides
    cvt.s64.s32 %rd25, %r12;
    cvt.s64.s32 %rd26, %r13;
    mul.lo.s64 %rd27, %rd25, %rd26;   // sYHW = Hout*Wout
    cvt.s64.s32 %rd28, %r11;
    mul.lo.s64 %rd29, %rd28, %rd27;   // sYc = Dout*Hout*Wout
    cvt.s64.s32 %rd30, %r6;
    mul.lo.s64 %rd31, %rd30, %rd29;   // sYn = Cout*Dout*Hout*Wout

    mul.lo.s64 %rd33, %rd18, %rd31;   // n_off = n*sYn

    cvt.s64.s32 %rd40, %r28;
    mul.lo.s64 %rd41, %rd40, %rd27;   // od*sYHW
    cvt.s64.s32 %rd42, %r27;
    mul.lo.s64 %rd43, %rd42, %rd26;   // oh*Wout
    add.s64 %rd44, %rd41, %rd43;
    cvt.s64.s32 %rd45, %r25;
    add.s64 %rd46, %rd44, %rd45;      // spatial_off

    add.s64 %rd47, %rd33, %rd46;      // n_off + spatial_off

    mov.u32 %r60, smem_patch;         // shared base address

    mov.u32 %r61, %r23;               // idx = tid
L_FILL_LOOP:
    setp.ge.s32 %p1, %r61, %r33;
    @%p1 bra L_FILL_DONE;

    div.s32 %r62, %r61, %r32;   // cin_local
    rem.s32 %r63, %r61, %r32;   // rem1
    div.s32 %r64, %r63, %r31;   // kd
    rem.s32 %r65, %r63, %r31;   // rem2
    div.s32 %r66, %r65, %r7;    // kh
    rem.s32 %r67, %r65, %r7;    // kw

    mul.lo.s32 %r68, %r28, %r8;
    sub.s32 %r69, %r68, %r9;
    mul.lo.s32 %r70, %r64, %r10;
    add.s32 %r71, %r69, %r70;   // id

    mul.lo.s32 %r72, %r27, %r8;
    sub.s32 %r73, %r72, %r9;
    mul.lo.s32 %r74, %r66, %r10;
    add.s32 %r75, %r73, %r74;   // ih

    mul.lo.s32 %r76, %r25, %r8;
    sub.s32 %r77, %r76, %r9;
    mul.lo.s32 %r78, %r67, %r10;
    add.s32 %r79, %r77, %r78;   // iw

    setp.lt.s32 %p2, %r71, 0;
    setp.ge.s32 %p3, %r71, %r3;
    or.pred %p4, %p2, %p3;
    setp.lt.s32 %p5, %r75, 0;
    setp.ge.s32 %p6, %r75, %r4;
    or.pred %p7, %p5, %p6;
    or.pred %p8, %p4, %p7;
    setp.lt.s32 %p9, %r79, 0;
    setp.ge.s32 %p10, %r79, %r5;
    or.pred %p11, %p9, %p10;
    or.pred %p12, %p8, %p11;

    mov.f32 %f1, 0f00000000;
    @%p12 bra L_STORE_SMEM;

    add.s32 %r80, %r29, %r62;
    cvt.s64.s32 %rd50, %r80;
    mul.lo.s64 %rd51, %rd50, %rd15;
    add.s64 %rd52, %rd19, %rd51;

    cvt.s64.s32 %rd53, %r71;
    mul.lo.s64 %rd54, %rd53, %rd13;
    add.s64 %rd55, %rd52, %rd54;

    cvt.s64.s32 %rd56, %r75;
    mul.lo.s64 %rd58, %rd56, %rd12;
    add.s64 %rd59, %rd55, %rd58;

    cvt.s64.s32 %rd60, %r79;
    add.s64 %rd61, %rd59, %rd60;

    shl.b64 %rd62, %rd61, 2;
    add.s64 %rd63, %rd5, %rd62;
    ld.global.f32 %f1, [%rd63];

L_STORE_SMEM:
    mul.lo.s32 %r81, %r61, 4;
    add.s32 %r82, %r60, %r81;
    st.shared.f32 [%r82], %f1;

    add.s32 %r61, %r61, %r24;
    bra L_FILL_LOOP;
L_FILL_DONE:

    bar.sync 0;

    cvt.s64.s32 %rd70, %r33;   // patchSize as s64

    mov.u32 %r90, %r23;        // co_local = tid
L_CO_LOOP:
    setp.ge.s32 %p13, %r90, %r15;
    @%p13 bra L_CO_DONE;

    add.s32 %r91, %r30, %r90;   // co

    mov.f32 %f2, 0f00000000;
    setp.eq.s64 %p14, %rd3, 0;
    @%p14 bra L_BIAS_DONE2;
    cvt.s64.s32 %rd71, %r91;
    shl.b64 %rd72, %rd71, 2;
    add.s64 %rd73, %rd8, %rd72;
    ld.global.f32 %f2, [%rd73];
L_BIAS_DONE2:

    cvt.s64.s32 %rd74, %r91;
    mul.lo.s64 %rd75, %rd74, %rd70;
    shl.b64 %rd76, %rd75, 2;
    add.s64 %rd77, %rd6, %rd76;

    mov.u32 %r92, %r60;
    mov.u64 %rd78, %rd77;
    mov.u32 %r93, 0;
L_ACC_LOOP:
    setp.ge.s32 %p15, %r93, %r33;
    @%p15 bra L_ACC_DONE;

    ld.shared.f32 %f3, [%r92];
    ld.global.f32 %f4, [%rd78];
    fma.rn.f32 %f2, %f3, %f4, %f2;

    add.s32 %r92, %r92, 4;
    add.s64 %rd78, %rd78, 4;
    add.s32 %r93, %r93, 1;
    bra L_ACC_LOOP;
L_ACC_DONE:

    cvt.s64.s32 %rd80, %r91;
    mul.lo.s64 %rd81, %rd80, %rd29;
    add.s64 %rd82, %rd47, %rd81;
    shl.b64 %rd83, %rd82, 2;
    add.s64 %rd84, %rd7, %rd83;
    st.global.f32 [%rd84], %f2;

    add.s32 %r90, %r90, %r24;
    bra L_CO_LOOP;
