import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a CTA-tiled 3D convolution.
#
# Structural optimization applied: CTA-level spatial (H,W) output tiling with
# shared-memory staging of the reusable input tile. Each CTA is responsible
# for a TILE_H x TILE_W (16x16) block of output pixels for a fixed (n, co, od)
# triple. For every (cin, kd) pair, the CTA cooperatively loads the
# corresponding 2D input patch (covering the halo needed for all kh/kw and
# all threads in the tile) into shared memory once, then every thread in the
# CTA reuses that shared data for its own kh/kw accumulation instead of
# re-reading global memory redundantly. This removes the massive redundant
# global-memory traffic that a pure "one thread per output, direct global
# loads" kernel incurs, while preserving exact stride/padding/dilation/groups
# semantics.
